document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&actions[b.dataset.action]){e.preventDefault();const mutating=['save-editor','save-grid','save-timenet','save-storage','save-criteria','cancel-consult'].includes(b.dataset.action),m=mutating?M:null;if(mutating&&b.disabled)return;if(mutating){b.disabled=true;if(m)m.busy=true}try{await actions[b.dataset.action](b)}catch(err){if(M)errorBox(err.message);else toast(err.message,true)}finally{if(mutating)b.disabled=false;if(m)m.busy=false}return}const th=e.target.closest('th[data-sort]');if(th&&th.dataset.sort!=='_action'){const k=th.dataset.sort,old=S.sort.find(x=>x.key===k),d=old?.dir===1?-1:1;S.sort=e.shiftKey?S.sort.filter(x=>x.key!==k):[];S.sort.push({key:k,dir:d});drawGrid()}});
